-- 20261107090000 postcheck（唯讀，套用 migration 後在正式庫執行）
-- Q1 方案與網紅價：正常＝16 列；display_order 1～4 是單間 4 個、enabled = false；display_order 11～22 是包棟 12 個、enabled = true
--    kol_*＝原價打七折後的實收：min(售價, 原價 − round(原價×30%))，與前台、validate-order-prices、建單觸發器同公式
SELECT p.display_order, p.name, p.enabled, p.numeric_code, p.guest_count_max, p.room_type_ids, p.tier_prices #>> '{weekday,sale}' AS wk_sale, p.tier_prices #>> '{weekday,original}' AS wk_orig, LEAST((p.tier_prices #>> '{weekday,sale}')::int, (p.tier_prices #>> '{weekday,original}')::int - ROUND((p.tier_prices #>> '{weekday,original}')::numeric * 30 / 100.0)::int) AS kol_wk, p.tier_prices #>> '{friday_sunday,sale}' AS fs_sale, p.tier_prices #>> '{friday_sunday,original}' AS fs_orig, LEAST((p.tier_prices #>> '{friday_sunday,sale}')::int, (p.tier_prices #>> '{friday_sunday,original}')::int - ROUND((p.tier_prices #>> '{friday_sunday,original}')::numeric * 30 / 100.0)::int) AS kol_fs, p.tier_prices #>> '{weekend,sale}' AS we_sale, p.tier_prices #>> '{weekend,original}' AS we_orig, LEAST((p.tier_prices #>> '{weekend,sale}')::int, (p.tier_prices #>> '{weekend,original}')::int - ROUND((p.tier_prices #>> '{weekend,original}')::numeric * 30 / 100.0)::int) AS kol_we, p.applicable_tiers FROM public.accommodation_packages p WHERE p.accommodation_id = 'a4bacadc-9b7a-4110-ac04-a1cc6248c822' ORDER BY p.display_order;
-- Q2 專案對方案：正常＝16 列；12 個包棟專案 package_name 有值、不重複、package_enabled true、價格＝方案原價；4 個單間專案（1101～1104）package_name 空白（default_package_id NULL）、價格與 precheck P4 相同
SELECT t.numeric_code, t.template_name, t.default_package_id, p.name AS package_name, p.numeric_code AS package_code, p.enabled AS package_enabled, t.weekday_price, t.peak_price, t.weekend_price FROM public.pricing_templates t LEFT JOIN public.accommodation_packages p ON p.id = t.default_package_id WHERE t.accommodation_id = 'a4bacadc-9b7a-4110-ac04-a1cc6248c822' ORDER BY t.numeric_code;
-- Q3 網紅碼：正常＝3 列，tpl_count 都是 12
SELECT d.code, jsonb_array_length(d.applicable_pricing_template_ids) AS tpl_count FROM public.discount_codes d WHERE d.code IN ('AMILE77', 'KWYTMIO', 'MIE20') ORDER BY 1;
-- Q4 flags：正常＝1 列：new_price_ui_enabled true、new_order_dialog_enabled false、price_sync_mode package_original、auto_template_enabled false
SELECT f.new_price_ui_enabled, f.new_order_dialog_enabled, f.price_sync_mode, f.auto_template_enabled FROM public.accommodation_info_flags f WHERE f.accommodation_id = 'a4bacadc-9b7a-4110-ac04-a1cc6248c822';
-- Q5 KOL 訂單：正常＝與 precheck P6 逐欄完全相同（updated_at 也不變）
SELECT o.order_number, o.order_source, o.final_price, o.pricing_template_id, o.package_id, o.check_in_date, o.order_status, o.updated_at FROM public.orders o WHERE o.order_number IN ('DM3A89R8', 'QW9M94K4', 'NE6Y99A5') ORDER BY 1;
-- Q6 總數摘要：正常＝packages 16、enabled_whole 12、disabled_single 4、templates 16、linked 12、future_pdp 0、backup_rows 34
SELECT (SELECT count(*) FROM public.accommodation_packages p WHERE p.accommodation_id = 'a4bacadc-9b7a-4110-ac04-a1cc6248c822') AS packages, (SELECT count(*) FROM public.accommodation_packages p WHERE p.accommodation_id = 'a4bacadc-9b7a-4110-ac04-a1cc6248c822' AND p.enabled AND p.name LIKE '%包棟') AS enabled_whole, (SELECT count(*) FROM public.accommodation_packages p WHERE p.accommodation_id = 'a4bacadc-9b7a-4110-ac04-a1cc6248c822' AND NOT p.enabled AND p.name IN ('雙人房(山景)', '雙人房(樹景)', '四人房(山景)', '四人房(樹景)')) AS disabled_single, (SELECT count(*) FROM public.pricing_templates t WHERE t.accommodation_id = 'a4bacadc-9b7a-4110-ac04-a1cc6248c822') AS templates, (SELECT count(*) FROM public.pricing_templates t WHERE t.accommodation_id = 'a4bacadc-9b7a-4110-ac04-a1cc6248c822' AND t.default_package_id IS NOT NULL) AS linked, (SELECT count(*) FROM public.package_date_prices d JOIN public.accommodation_packages p ON p.id = d.package_id WHERE p.accommodation_id = 'a4bacadc-9b7a-4110-ac04-a1cc6248c822' AND d.date >= CURRENT_DATE) AS future_pdp, (SELECT count(*) FROM public.sijishanyu_price_v2_backup_20261107) AS backup_rows;
-- Q7 單間專案指紋：正常＝4 列、default_package_id 全 NULL、row_md5 與 precheck P11 逐列完全相同
SELECT t.id, t.template_name, t.default_package_id, t.weekday_price, t.peak_price, t.weekend_price, t.price, md5(to_jsonb(t)::text) AS row_md5 FROM public.pricing_templates t WHERE t.id IN ('a247bcaf-74df-49e6-a1e1-d12b1d681263', '7a6e0125-8fd4-4f03-aa6c-37cf75b94bc0', 'a32485b3-57a4-4c24-9c7e-12576ab508ce', '7195c9b1-0a11-4148-a510-467af8fdecbf') ORDER BY t.id;
